    def _path_change(self,root,path,mode,value=None,expected=not_found):
        elems=self._get_elements_and_details(path)
        if not elems:
            if mode in ('set','replace'):return value
            raise DeltaError('Cannot remove the root object')
        def walk(obj,index):
            elem,action=elems[index]
            last=index==len(elems)-1
            if last:
                if mode=='insert':
                    if action==GETATTR: raise DeltaError('Cannot insert an attribute')
